// File: rules.rs
	#[verifier::external_body]
proof fn always_unfold<T>(ex: Execution<T>, p: TempPred<T>)
    requires always(p).satisfied_by(ex),
    ensures forall |i: nat| p.satisfied_by(#[trigger] ex.suffix(i)),
	{
		unimplemented!()
	}

proof fn always_distributed_by_and<T>(p: TempPred<T>, q: TempPred<T>)
    ensures valid(always(p.and(q)).implies(always(p).and(always(q)))),
{
    // `valid(r)` means: for all executions, `r` holds.
    forall |ex: Execution<T>| {
        // Unfold `implies` and `and` via their definitions.
        //
        // Goal: (always(p.and(q)).implies(always(p).and(always(q))))(ex)
        // == (always(p.and(q)).satisfied_by(ex) ==> always(p).and(always(q)).satisfied_by(ex))
        assert(
            always(p.and(q)).satisfied_by(ex)
                ==> always(p).and(always(q)).satisfied_by(ex)
        );

        // Proof of the implication.
        if (always(p.and(q)).satisfied_by(ex)) {
            // Unfold `always`: it gives us p and q at every suffix.
            //
            // always(p.and(q))  == forall i. (p.and(q)).satisfied_by(ex.suffix(i))
            // (p.and(q)).satisfied_by(y) == p.satisfied_by(y) && q.satisfied_by(y)
            forall |i: nat| {
                // From `always(p.and(q))` at suffix i, derive both p and q.
                assert(p.satisfied_by(ex.suffix(i)));
                assert(q.satisfied_by(ex.suffix(i)));
            }

            // Now repackage into `always(p)` and `always(q)`.
            assert(always(p).satisfied_by(ex));
            assert(always(q).satisfied_by(ex));
        }
        // Finally, `always(p).and(always(q))` holds when both hold.
        if (always(p).satisfied_by(ex) && always(q).satisfied_by(ex)) {
            assert(always(p).and(always(q)).satisfied_by(ex));
        }
    };
}


}

